VALUES ((SELECT id FROM categories WHERE slug = 'faucets'),
  'Shower Fixtures', 'P5931302', 'p5931302',
  'Hand Shower — PVD Satin Nickel', 'Huntington Brass', 'Contemporary square style', 'The Huntington Brass contemporary styled single setting hand shower. Designed of a lightweight ABS construction, this hand shower is an excellent item to add to your shower or tub for a modern contemporary style.\n\nFeatures:\n• Contemporary square style.\n• All ABS construction.\n• Single setting spray.\n• East to clean tips.\n• Standard 1/2” connection.\n• Available in four finishes: Polished Chrome, PVD Satin Nickel, PVD Satin Brass and Matte Black.\n\nSpecification\nSheet\n\n• Contemporary square style\n• All ABS construction\n• Single setting spray\n• Easy to clean tips\n• Standard 1/2” connection\n• 1.5 GPM',
  81.9, NULL, 'PVD Satin Nickel', '091878593923',
  0.44, 2.36, 2.36, 8.66,
  'https://cdn.shopify.com/s/files/1/0614/9626/2730/files/P5931302_9b83213e-39b4-4398-b855-6f3d732b5dc8.jpg?v=1742842748', 'csv', 1)
ON DUPLICATE KEY UPDATE
  category_id = VALUES(category_id), product_type = VALUES(product_type),
