  upc = COALESCE(upc, VALUES(upc)), weight_lbs = VALUES(weight_lbs),
  width_in = VALUES(width_in), depth_in = VALUES(depth_in),
  height_in = VALUES(height_in), primary_image_url = VALUES(primary_image_url);

