   primary_image_url, source_flag, is_active)
VALUES ((SELECT id FROM categories WHERE slug = 'faucets'),
  'Shower Fixtures', 'P6381649', 'p6381649',
  'Tazio Tub & Shower — Matte Black', 'Huntington Brass', 'Tazio metal lever handle', 'Simply modern. The Tazio tub and shower package with its minimalist lever handle and captivating design will enhance the modern style of your shower. The Tazio tub and shower package works in conjunction with our latest diverter shower valve so that the shower experience is easily changed between the bath tub spout to shower head with just a turn of the handle.\n\nFeatures:\n• 6" Face single setting showerhead with shower arm and flange.\n• Valve face plate trim with easy to grasp lever handle.\n• Matching minimalist tub spout.\n• Available in four finishes: Polished Chrome, Satin Nickel, PVD Satin Brass and Matte Black.\n\n• Face plate marked H and C on both sides of handle for P4323199 diverter valve only.\n\n• Valve sold separately. Huntington Brass recommends this Rough-in shower valve for this trim package - (P4323199).\n\nSpecification\nSheet\n\n• Tazio metal lever handle\n• 6” Round shower head\n• Single Setting shower head\n• 1.5 GPM shower head',
  273.9, NULL, 'Matte Black', '091878586369',
  3.31, 7.28, 9.06, 3.15,
  'https://cdn.shopify.com/s/files/1/0614/9626/2730/files/P6381649.jpg?v=1770231258', 'csv', 1)
ON DUPLICATE KEY UPDATE
  category_id = VALUES(category_id), product_type = VALUES(product_type),
  name = VALUES(name), brand = VALUES(brand),
  short_desc = VALUES(short_desc), long_desc = VALUES(long_desc),
  price = VALUES(price), color = VALUES(color),
  upc = COALESCE(upc, VALUES(upc)), weight_lbs = VALUES(weight_lbs),
  width_in = VALUES(width_in), depth_in = VALUES(depth_in),
  height_in = VALUES(height_in), primary_image_url = VALUES(primary_image_url);

